def get_adjacent_positions(position):
    row = position // len(grid[0])
    col = position % len(grid[0])

    # Check if up is a valid position
    if row > 0 and grid[row-1][col] != 'X':
        yield (row-1, col)

    # Check if down is a valid position
    if row < len(grid) - 1 and grid[row+1][col] != 'X':
        yield (row+1, col)

    # Check if left is a valid position
    if col > 0 and grid[row][col-1] != 'X':
        yield (row, col-1)

    # Check if right is a valid position
    if col < len(grid[0]) - 1 and grid[row][col+1] != 'X':
        yield (row, col+1)

# Function to add states to the dictionary
def add_state(position):
    state = {"position": position, "cost": 0}

    # Get adjacent positions for the current state
    for adj_position in get_adjacent_positions(position):
        if adj_position not in states:
            add_state(adj_position)

        state["adjacent_states"] = [adj_position]
        for adj_adj_position in get_adjacent_positions(adj_position):
            if adj_adj_position not in states[adj_position]["adjacent_states"]:
